define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_6.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e80883","topics":[]},{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_Parent_9.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e80985","topics":[]},{"title":"Removing the magnet rear trim ring","shortdesc":"<p class=\"shortdesc\">Removes the rear trim ring from the rear endbell.  The trim ring covers the bolts securing the magnet rear enclosures.<\/p>","href":"t_RemovingTheRearTrimRing_7.html","attributes":{"data-id":"id_2002972"},"menu":{"hasChildren":false},"tocID":"id_2002972-d46e81088","topics":[]},{"title":"Removing the magnet rear cable cover","shortdesc":"<p class=\"shortdesc\">Removes the rear cable cover from the magnet enclosure.<\/p>","href":"t_RemovingTheRearCableCover_6.html","attributes":{"data-id":"id_2002978"},"menu":{"hasChildren":false},"tocID":"id_2002978-d46e81190","topics":[]},{"title":"Removing the rear pedestal covers","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RemovingRearPedestalCovers_5.html","attributes":{"data-id":"id_2008055"},"menu":{"hasChildren":false},"tocID":"id_2008055-d46e81292","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_14.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e81393","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_13.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e81495","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_11.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e81597","topics":[]},{"title":"Removing the magnet left-hand lower rear cover","shortdesc":"<p class=\"shortdesc\">Removes the lower cover from the left-hand rear corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandLowerRearCover_3.html","attributes":{"data-id":"id_2002991"},"menu":{"hasChildren":false},"tocID":"id_2002991-d46e81699","topics":[]},{"title":"Removing the magnet left-hand rear cover","shortdesc":"<p class=\"shortdesc\">Removes the rear cover from the left-hand side of the magnet.<\/p>","href":"t_RemovingTheLeftHandRearCover.html","attributes":{"data-id":"id_2002980"},"menu":{"hasChildren":false},"tocID":"id_2002980-d46e81801","topics":[]}]});